export const VIEWBOX = '0 0 120 120';

/* ======================================================================
   甲虫大名录的体型轮廓（beetle-form-*）
   为什么要参数化：名录有 48 个类群，逐个画写实标本图不现实；但让 46 个类群
   共用同一张通用轮廓等于没有图——体型比例、触角形状、鞘翅长度恰恰是分科时
   最先看的三件事。所以把「甲虫都长这样」的骨架收敛成一个生成器，各科只描述
   自己的识别特征，得到的图既彼此不同，又不必逐张手绘。
   这些图是「典型体型」而不是某一个物种的写生，页面上也如实这么标注。
   ====================================================================== */

/* 触角：形状本身就是分类特征，所以分型而不是统一画一根丝。 */
const antenna = (kind, x, y, ink) => {
  const L = (d, w = 2.6) => leg(d, ink, w);
  const dx = x - 60;
  const m = (d) => d;
  switch (kind) {
    case 'club':      /* 棒状：末端膨大成小锤（葬甲、阎甲、露尾甲） */
      return L(`M${x} ${y} C${x + dx * 0.9} ${y - 9} ${x + dx * 1.5} ${y - 13} ${x + dx * 1.9} ${y - 16}`)
        + `<ellipse cx="${x + dx * 2.1}" cy="${y - 18}" rx="4" ry="3.4" fill="${ink}"/>`;
    case 'elbow':     /* 肘状：先斜出再折向前（象甲） */
      return L(`M${x} ${y} L${x + dx * 1.7} ${y - 6} L${x + dx * 2.2} ${y - 17}`);
    case 'saw':       /* 锯齿状：一侧带齿（叩甲、吉丁） */
      return L(`M${x} ${y} C${x + dx * 1.1} ${y - 8} ${x + dx * 1.7} ${y - 13} ${x + dx * 2} ${y - 19}`)
        + L(`M${x + dx * 1.2} ${y - 8} l${dx * 0.35} -3 M${x + dx * 1.5} ${y - 12} l${dx * 0.35} -3 M${x + dx * 1.8} ${y - 16} l${dx * 0.3} -3`, 1.6);
    case 'fan':       /* 鳃片状：末端张开成小扇（金龟类） */
      return L(`M${x} ${y} C${x + dx * 1.1} ${y - 7} ${x + dx * 1.5} ${y - 10} ${x + dx * 1.8} ${y - 13}`)
        + `<path d="M${x + dx * 1.8} ${y - 13} l${dx * 0.9} -5 l${dx * 0.1} 7 Z" fill="${ink}"/>`;
    case 'short':     /* 很短：微小甲虫常见 */
      return L(`M${x} ${y} C${x + dx * 0.8} ${y - 5} ${x + dx * 1.1} ${y - 7} ${x + dx * 1.3} ${y - 9}`, 3);
    case 'long':      /* 极长：向后甩过身体 */
      return L(`M${x} ${y} C${x + dx * 2.6} ${y - 14} ${x + dx * 3.6} ${y + 6} ${x + dx * 3.2} ${y + 32}`, 2.4);
    default:          /* 丝状 */
      return L(`M${x} ${y} C${x + dx * 1.2} ${y - 10} ${x + dx * 1.9} ${y - 15} ${x + dx * 2.4} ${y - 20}`);
  }
};

/* 腿：末端形状说明它在哪儿干活。 */
const legSet = (kind, hw, ey0, ey1, ink) => {
  const L = (d, w = 3.2) => leg(d, ink, w);
  const span = ey1 - ey0;
  const rows = [ey0 + 2, ey0 + span * 0.32, ey0 + span * 0.62];
  const out = [];
  rows.forEach((y, i) => {
    const reach = kind === 'long' ? 26 : kind === 'paddle' ? 20 : 17;
    const drop = i === 0 ? -14 : i === 1 ? 4 : 20;
    [-1, 1].forEach((sx) => {
      const x0 = 60 + sx * (hw - 2);
      const x1 = x0 + sx * reach;
      const y1 = y + drop;
      out.push(L(`M${x0} ${y} C${x0 + sx * reach * 0.6} ${y + drop * 0.3} ${x1} ${y1 - drop * 0.3} ${x1} ${y1}`,
        kind === 'dig' && i === 0 ? 4.6 : 3.2));
      if (kind === 'paddle' && i === 2) {
        /* 游泳足：末端一片桨，边上带缘毛 */
        out.push(`<path d="M${x1} ${y1} q${sx * 10} 3 ${sx * 13} 11 q${sx * -9} -1 ${sx * -14} -6 Z" fill="${ink}" opacity=".85"/>`);
      } else if (kind === 'dig' && i === 0) {
        /* 挖掘足：宽扁带齿 */
        out.push(`<path d="M${x1} ${y1} l${sx * 9} -3 l${sx * 1} 7 l${sx * -9} 2 Z" fill="${ink}"/>`
          + L(`M${x1 + sx * 3} ${y1 + 5} l${sx * 2} 3 M${x1 + sx * 7} ${y1 + 3} l${sx * 2} 3`, 1.6));
      } else if (kind === 'grip') {
        /* 抓握足：末端一对钩爪 */
        out.push(L(`M${x1} ${y1} l${sx * 4} -3 M${x1} ${y1} l${sx * 4} 3`, 1.8));
      }
    });
  });
  return out.join('');
};

/* 名录体型轮廓生成器。坐标系 0..120，中线 x=60。 */
const form = (o) => {
  const shell = o.shell || '#6b4a22';
  const dark = o.dark || '#241608';
  const ink = o.ink || dark;
  const hw = o.hw == null ? 21 : o.hw;          /* 鞘翅半宽 */
  const ey0 = o.ey0 == null ? 42 : o.ey0;       /* 鞘翅前缘 */
  const ey1 = o.ey1 == null ? 104 : o.ey1;      /* 鞘翅末端 */
  const taper = o.taper == null ? 0.78 : o.taper;
  const belly = o.belly || 0;                   /* 鞘翅盖不住、露在后面的腹部 */
  const ph = o.ph == null ? 14 : o.ph;          /* 前胸高 */
  const pw = o.pw == null ? hw * 0.78 : o.pw;   /* 前胸半宽 */
  const hh = o.hh == null ? 12 : o.hh;          /* 头高 */
  const hwd = o.hwd == null ? pw * 0.72 : o.hwd;/* 头半宽 */
  const span = ey1 - ey0;
  const proTop = ey0 - ph;
  const headBottom = proTop + 2;
  const headTop = headBottom - hh;

  const half = (sx) => {
    const xw = 60 + sx * hw;
    const xt = 60 + sx * hw * taper;
    return `M60 ${ey0} C${xw} ${ey0} ${xw} ${ey0 + span * 0.52} ${xt} ${ey1 - span * 0.08} C${xt} ${ey1} 60 ${ey1} 60 ${ey1} Z`;
  };

  const parts = [shadow(60, Math.min(116, ey1 + belly + 6), hw + 4, 4, 0.14)];
  parts.push(legSet(o.legs || 'short', hw, ey0, ey1, ink));
  parts.push(antenna(o.ant || 'thread', 60 - hwd * 0.6, headTop + 4, ink));
  parts.push(antenna(o.ant || 'thread', 60 + hwd * 0.6, headTop + 4, ink));
  if (o.snout) parts.push(o.snout);
  /* 头 */
  parts.push(`<path d="M${60 - hwd} ${headBottom} C${60 - hwd} ${headTop} ${60 + hwd} ${headTop} ${60 + hwd} ${headBottom} Z" fill="${dark}"/>`);
  parts.push(`<circle cx="${60 - hwd * 0.55}" cy="${headTop + hh * 0.5}" r="${o.bigEye ? 3.4 : 2.2}" fill="#0a0705"/>`);
  parts.push(`<circle cx="${60 + hwd * 0.55}" cy="${headTop + hh * 0.5}" r="${o.bigEye ? 3.4 : 2.2}" fill="#0a0705"/>`);
  /* 露出的腹部先画，才会被鞘翅压住前段 */
  if (belly) {
    parts.push(`<path d="M${60 - hw * taper * 0.92} ${ey1 - 6} C${60 - hw * taper * 0.8} ${ey1 + belly} ${60 + hw * taper * 0.8} ${ey1 + belly} ${60 + hw * taper * 0.92} ${ey1 - 6} Z" fill="${o.bellyFill || '#7c5a34'}" stroke="${dark}" stroke-width="1.6"/>`);
    const seams = [];
    for (let i = 1; i <= 3; i++) {
      const y = ey1 - 2 + (belly * i) / 4;
      seams.push(`M${60 - hw * taper * 0.7} ${y} Q60 ${y + 3} ${60 + hw * taper * 0.7} ${y}`);
    }
    parts.push(`<path d="${seams.join(' ')}" fill="none" stroke="${dark}" stroke-width="1.2" opacity=".55"/>`);
  }
  /* 前胸背板 */
  parts.push(`<path d="M${60 - pw * 0.66} ${proTop} C${60 - pw} ${proTop + ph * 0.4} ${60 - pw} ${ey0 - 1} ${60 - pw} ${ey0} L${60 + pw} ${ey0} C${60 + pw} ${ey0 - 1} ${60 + pw} ${proTop + ph * 0.4} ${60 + pw * 0.66} ${proTop} Z" fill="${o.pro || dark}" stroke="${dark}" stroke-width="1.6"/>`);
  if (o.proMark) parts.push(o.proMark);
  /* 两片鞘翅 + 中缝 */
  parts.push(`<path d="${half(-1)}" fill="${shell}"/>`);
  parts.push(`<path d="${half(1)}" fill="${o.shell2 || shell}"/>`);
  parts.push(`<path d="M60 ${ey0} L60 ${ey1}" stroke="${dark}" stroke-width="1.6" opacity=".9"/>`);
  parts.push(`<path d="${half(-1)}" fill="none" stroke="${dark}" stroke-width="1.8"/>`);
  parts.push(`<path d="${half(1)}" fill="none" stroke="${dark}" stroke-width="1.8"/>`);
  if (o.extra) parts.push(o.extra);
  if (o.gloss !== false) {
    parts.push(`<path d="M${60 - hw * 0.72} ${ey0 + span * 0.12} C${60 - hw * 0.9} ${ey0 + span * 0.4} ${60 - hw * 0.85} ${ey0 + span * 0.72} ${60 - hw * 0.7} ${ey1 - span * 0.12}" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" opacity=".22"/>`);
  }
  return '\n  ' + parts.join('\n  ') + '\n';
};

/* 鞘翅上的纵沟／纵脊：步甲、黑艳甲、红萤都靠这个认。 */
const ridges = (hw, ey0, ey1, color, n = 3, op = 0.5) => {
  const span = ey1 - ey0;
  const out = [];
  for (let i = 1; i <= n; i++) {
    const f = (i / (n + 1)) * 0.86;
    [-1, 1].forEach((sx) => {
      const x = 60 + sx * hw * f;
      out.push(`M${x} ${ey0 + span * 0.12} C${x + sx * 2} ${ey0 + span * 0.45} ${x + sx * 1.5} ${ey0 + span * 0.75} ${x - sx * 1} ${ey1 - span * 0.1}`);
    });
  }
  return `<path d="${out.join(' ')}" fill="none" stroke="${color}" stroke-width="1.1" opacity="${op}"/>`;
};

const spots = (list, color, op = 0.9) =>
  `<g fill="${color}" opacity="${op}">` +
  list.map(([cx, cy, r]) => `<ellipse cx="${cx}" cy="${cy}" rx="${r}" ry="${r * 0.82}"/>`).join('') +
  '</g>';

/* ---- 原鞘亚目 ---- */
